-- A sheet: the unit everything else in the app is kept per. Created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(64) PRIMARY KEY,
    created_at TIMESTAMP   NOT NULL
);
-- The sheet's "today": the date every date-dependent decision and default date on the sheet uses,
-- never the real clock. A new sheet starts on the real date; it is changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE);
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- A person on a sheet: a name and a grade (A, B or C). Listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on the sheet, ignoring case and surrounding spaces. Names are kept
-- with surrounding spaces removed; name_key is the name lower-cased, the key the uniqueness is on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A claim a person on a sheet makes: an amount (0.00 or more, two decimals), a date and a note
-- (may be empty). Listed under its person newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(64)    NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
package net.officefloor.hq.app;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Spring Boot host: serves the SPA from static/, with H2 + Flyway (schema migrated on boot) and
 * Actuator. Domain REST endpoints, @Service/@Repository beans and migrations are added under
 * src/main/java and src/main/resources.
 */
@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Records outside a transaction are appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/**
 * The signed-in user, as the screen sends it on every change in the {@link #HEADER} header,
 * URI-encoded so any typed name fits in a header.
 */
public final class SignedIn {

    public static final String HEADER = "X-User";

    private SignedIn() {
    }

    /** The user's name from the header's value. */
    public static String name(String header) {
        return URLDecoder.decode(header.replace("+", "%2B"), StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.resource.PathResourceResolver;

/**
 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
 */
@Configuration
public class SpaConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/**")
                .addResourceLocations("classpath:/static/")
                .resourceChain(true)
                .addResolver(new PathResourceResolver() {
                    @Override
                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
                        if (resourcePath.startsWith("api/")) {
                            return null; // let the API handle / 404 it
                        }
                        Resource requested = location.createRelative(resourcePath);
                        return (requested.exists() && requested.isReadable())
                                ? requested
                                : location.createRelative("index.html");
                    }
                });
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** What the screen is told about a person. */
    public record PersonView(long id, String name, String grade) {

        static PersonView of(Person person) {
            return new PersonView(person.getId(), person.getName(), person.getGrade());
        }
    }

    /** A person's values as entered on the form: a name is required, the grade is A, B or C. */
    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(PersonView::of).toList();
    }

    /** Add a person to the sheet. */
    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonForm form) {
        return PersonView.of(service.add(sheetId, SignedIn.name(user), form.name(), form.grade()));
    }

    /** Change a person's name and grade. */
    @PutMapping("/{personId}")
    public PersonView edit(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonForm form) {
        return PersonView.of(service.edit(sheetId, SignedIn.name(user), personId, form.name(), form.grade()));
    }

    /** Another user took the name between the check and the write: the unique index refuses it. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameTaken() {
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
